<template><section v-draft="{ value: {form,file}, resetKey: saved }" class="roster-import"><h2>{{ team?'导入新的正式名单':'新建队伍并上传名单' }}</h2><p>管理员可在报名或名单修改时间外直接导入。负责人和队员可先录入学号、姓名；账号信息一致并通过当季学籍审核后自动关联。预览确认后名单立即生效。</p><button type="button" :disabled="busy" @click="download">下载名单模板</button><p v-if="error" class="import-error" role="alert">{{ error }}</p><p v-if="success" role="status">{{ success }}</p>
  <form @submit.prevent="preview"><fieldset :disabled="busy"><label>队伍名称<input v-model="form.team_name" required maxlength="100"></label><label>赛事类型<select aria-label="赛事类型" v-model="form.league_type" required :disabled="!!team"><option value="">请选择赛事</option><CompetitionOptions :season-id="seasonId" /></select></label><label>负责人当前学号<input v-model="form.manager_student_id" required maxlength="50"></label><label>负责人姓名<input v-model="form.manager_name" required maxlength="100"></label><div class="colors"><label>上衣主要颜色<input v-model="form.shirt_color" placeholder="选填，未填显示 /" maxlength="50"></label><label>裤子主要颜色<input v-model="form.shorts_color" placeholder="选填，未填显示 /" maxlength="50"></label><label>袜子主要颜色<input v-model="form.socks_color" placeholder="选填，未填显示 /" maxlength="50"></label></div><label>新版名单 Excel<input :key="fileKey" type="file" accept=".xls,.xlsx" required @change="file=$event.target.files[0];result=null"></label><button :disabled="!seasonId||!file">预览导入名单</button></fieldset></form>
  <section v-if="result" class="import-preview"><h3>导入审核预览</h3><p>{{ result.metadata.team_name }} · {{ result.league_type }} · 负责人 {{ result.manager.name }}（{{ result.manager.student_id }}） · {{ linkLabel(result.manager.link_status) }}</p><p>上衣：{{ result.metadata.shirt_color || '/' }}；裤子：{{ result.metadata.shorts_color || '/' }}；袜子：{{ result.metadata.socks_color || '/' }}</p><p>{{ result.summary.total }} 人 · 待关联 {{ result.summary.unlinked }} 人 · 外援 {{ result.summary.foreign }} 人<template v-if="result.enable_sports_training"> · 运训 {{ result.summary.sports_training }} 人</template><template v-if="result.enable_football_specialty"> · 足球特长生 {{ result.summary.football_specialty }} 人</template> · 守门员 {{ result.summary.goalkeepers }} 人</p><p>{{ result.rules_text }}</p><ul v-if="result.errors.length" class="import-error"><li v-for="(e,i) in result.errors" :key="i">{{ e.row_number?'第 '+e.row_number+' 行：':'' }}{{ e.message }}</li></ul><div class="import-table"><table><thead><tr><th>行</th><th>学号／姓名</th><th>号码／角色与标记</th><th>学籍／同类赛事已通过球队数</th><th>材料</th></tr></thead><tbody><tr v-for="m in result.members" :key="m.row_number"><td>{{ m.row_number }}</td><td>{{ m.student_id }}<br>{{ m.name }}<br>{{ m.college }}</td><td>{{ m.jersey_number }}号<br>{{ m.is_captain?'队长 ':'' }}{{ m.is_goalkeeper?'守门员 ':'' }}{{ m.is_foreign?'外援 ':'' }}{{ result.enable_sports_training&&m.is_sports_training?'运训 ':'' }}{{ result.enable_football_specialty&&m.is_football_specialty?'足球特长生':'' }}<br>{{ m.remark }}</td><td>{{ linkLabel(m.link_status) }}／{{ m.approved_team_count }}</td><td><button :disabled="!m.registration_id||busy" @click="showMaterial(m.registration_id)">查看学籍</button></td></tr></tbody></table></div><p>人数、赛事标签及各赛事参队限制由管理员人工判断。有错误时请修正文件，再次预览。</p><button :disabled="busy||!result.can_confirm" @click="confirm">确认审核通过并立即导入</button></section>
  <section v-if="material"><h3>{{ material.account.name }}的学籍材料</h3><button @click="closeMaterial">关闭材料</button><PlayerAcademicImage v-if="material.files[0]?.available" :registration-id="material.registration.id" :file-id="material.files[0].id"/><p v-else>材料已清理或不可用。</p></section>
</section></template>
<script setup>
import CompetitionOptions from './CompetitionOptions.vue'
import {ref,watch} from 'vue'
import api from '../api/http'
import { requestKey } from '../utils/requestKey'
import PlayerAcademicImage from './PlayerAcademicImage.vue'
const props=defineProps({seasonId:[Number,String],team:Object}),emit=defineEmits(['confirmed']),form=ref({}),file=ref(null),fileKey=ref(0),result=ref(null),busy=ref(false),error=ref(''),success=ref(''),material=ref(null);const saved=ref(0);let key=requestKey(),sequence=0,materialSequence=0
const linkLabel=value=>({linked:'已关联账号',unregistered:'待注册及学籍审核',awaiting_approval:'待学籍审核',identity_mismatch:'姓名或学号不一致，待核实',disabled:'账号停用，暂不关联'}[value]||'待关联')
const fail=e=>error.value=e.response?.data?.message||'操作失败，请重试'
watch(()=>[props.team?.id,props.seasonId],()=>{sequence++;form.value={team_name:props.team?.team_name||'',league_type:props.team?.league_type||'',manager_student_id:'',manager_name:'',shirt_color:props.team?.shirt_color||'',shorts_color:props.team?.shorts_color||'',socks_color:props.team?.socks_color||''};result.value=null;file.value=null;fileKey.value++;error.value='';success.value='';material.value=null},{immediate:true})
watch(form,()=>{result.value=null;closeMaterial()},{deep:true})
function closeMaterial(){materialSequence++;material.value=null}
async function download(){try{const response=await api.get('/team/import-template',{responseType:'blob',params:{season_id:props.seasonId,league_type:form.value.league_type||undefined}});const url=URL.createObjectURL(response);const a=document.createElement('a');a.href=url;a.download='名单导入模板.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){fail(e)}}
async function preview(){busy.value=true;error.value='';success.value='';result.value=null;const n=sequence;try{const body=new FormData();Object.entries(form.value).forEach(([k,v])=>body.append(k,v));body.append('season_id',props.seasonId);if(props.team)body.append('team_id',props.team.id);body.append('roster_file',file.value);const r=await api.post('/team/import-preview',body,{headers:{'Content-Type':'multipart/form-data'}});if(n===sequence){result.value=r.data;key=requestKey()}}catch(e){if(n===sequence)fail(e)}finally{busy.value=false}}
async function confirm(){busy.value=true;error.value='';const n=sequence;try{const r=await api.post('/team/import-confirm',{preview:result.value.preview,preview_token:result.value.preview_token},{headers:{'Idempotency-Key':key}});if(n===sequence){saved.value++;result.value=null;success.value='审核通过，正式名单已立即生效。';emit('confirmed',r.data)}}catch(e){if(n===sequence)fail(e)}finally{busy.value=false}}
async function showMaterial(id){const n=++materialSequence;material.value=null;try{const r=await api.get('/player-admin/season-registrations/'+id);if(n===materialSequence)material.value=r.data}catch(e){if(n===materialSequence)fail(e)}}
</script>
<style scoped>
@layer legacy {
.roster-import{padding:18px;background:#fff;border:1px solid #dce5ed;border-radius:14px;overflow-wrap:anywhere}.roster-import h2{font-size:18px}.roster-import p{font-size:13px;line-height:1.7;color:#526477}.roster-import label{display:flex;flex-direction:column;gap:6px;margin:12px 0;font-size:14px}.roster-import input,.roster-import select{padding:10px;border:1px solid #cbd5e1;border-radius:8px;min-width:0;width:100%;box-sizing:border-box}.roster-import fieldset{border:0;margin:0;padding:0;min-width:0}.roster-import button{padding:10px 12px;border:0;border-radius:8px;background:#195c83;color:white;cursor:pointer}.roster-import button:disabled{opacity:.5;cursor:not-allowed}.colors{display:flex;gap:8px}.colors label{min-width:0;flex:1}.import-preview{margin-top:22px;border-top:1px solid #ccc}.import-table{overflow:auto}.import-table table{border-collapse:collapse;min-width:570px;width:100%}.import-table td,.import-table th{font-size:13px;padding:10px 6px;text-align:left;border-bottom:1px solid #ddd}.roster-import .import-error{color:#9f2136;background:#fff1f2;padding:12px}.import-error li{margin-left:15px}
}
</style>
